/* --- Inline lookup functions --- */

static inline uint8_t unicode_ccc(uint32_t cp) {
    if (cp >= 0x110000) return 0;
    return UNICODE_LOOKUP(unicode_ccc_stage1, unicode_ccc_stage2, cp);
}

static inline UnicodeGraphemeBreak unicode_grapheme_break(uint32_t cp) {
    if (cp >= 0x110000) return GBP_OTHER;
    return (UnicodeGraphemeBreak)UNICODE_LOOKUP(unicode_gbp_stage1, unicode_gbp_stage2, cp);
}

static inline UnicodeWordBreak unicode_word_break(uint32_t cp) {
    if (cp >= 0x110000) return WBP_OTHER;
    return (UnicodeWordBreak)UNICODE_LOOKUP(unicode_wbp_stage1, unicode_wbp_stage2, cp);
}

static inline UnicodeLineBreak unicode_line_break(uint32_t cp) {
    if (cp >= 0x110000) return LBP_XX;
    return (UnicodeLineBreak)UNICODE_LOOKUP(unicode_lbp_stage1, unicode_lbp_stage2, cp);
}

static inline uint8_t unicode_nfd_qc(uint32_t cp) {
    if (cp >= 0x110000) return 0; /* Yes */
    return UNICODE_LOOKUP(unicode_nfd_qc_stage1, unicode_nfd_qc_stage2, cp);
}

/* Returns pointer to decomposition data for cp, or NULL if no decomposition.
 * Format: data[0] = length, data[1..length] = decomposed codepoints. */
static inline const uint32_t* unicode_nfd_decomp(uint32_t cp) {
    if (cp >= 0x110000) return 0;
    uint16_t idx = UNICODE_LOOKUP(unicode_nfd_index_stage1, unicode_nfd_index_stage2, cp);
    if (idx == 0) return 0;
    return &unicode_nfd_data[idx];
}

